using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DivinePrismOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/DivinePrismOmenData")]
public class DivinePrismOmenData : OmenData
{
	[NonSerialized]
	private Action<int> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate(int corruptionAmount)
		{
			if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.PlayerTurn)
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				OmenLogic.ActivateOmen(null, corruptionAmount, null, null);
			}
		};
		ReferenceSingleton<MiscOmensHandler>.Instance.DivinePrismAction = omenAction;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.DivinePrismAction = null;
	}
}
